create table public.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text not null check(char_length(display_name) between 2 and 80),verification_status text not null default 'pending' check(verification_status in ('pending','verified','rejected')),created_at timestamptz not null default now());
create table public.venues(id uuid primary key default gen_random_uuid(),provider text not null,provider_place_id text not null,name text not null,latitude double precision not null check(latitude between -90 and 90),longitude double precision not null check(longitude between -180 and 180),public_verified boolean not null default false,unique(provider,provider_place_id));
create table public.pings(id uuid primary key default gen_random_uuid(),host_id uuid not null references public.profiles(user_id),venue_id uuid not null references public.venues(id),body text not null check(char_length(body) between 3 and 280),starts_at timestamptz not null,created_at timestamptz not null default now(),status text not null default 'draft' check(status in ('draft','published','cancelled')));
create table public.join_requests(id uuid primary key default gen_random_uuid(),ping_id uuid not null references public.pings(id),requester_id uuid not null references public.profiles(user_id),status text not null default 'pending' check(status in ('pending','approved','declined')),created_at timestamptz not null default now(),unique(ping_id,requester_id));
create table public.chat_messages(id uuid primary key default gen_random_uuid(),join_request_id uuid not null references public.join_requests(id),sender_id uuid not null references public.profiles(user_id),body text not null check(char_length(body) between 1 and 2000),created_at timestamptz not null default now());
create table public.user_blocks(blocker_id uuid not null references public.profiles(user_id),blocked_id uuid not null references public.profiles(user_id),created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(user_id),ping_id uuid references public.pings(id),reported_user_id uuid references public.profiles(user_id),reason text not null check(char_length(reason) between 3 and 1000),status text not null default 'open' check(status in ('open','reviewing','closed')),created_at timestamptz not null default now(),check(ping_id is not null or reported_user_id is not null));
alter table public.profiles enable row level security;alter table public.venues enable row level security;alter table public.pings enable row level security;alter table public.join_requests enable row level security;alter table public.chat_messages enable row level security;alter table public.user_blocks enable row level security;alter table public.reports enable row level security;
revoke all on public.profiles,public.venues,public.pings,public.join_requests,public.chat_messages,public.user_blocks,public.reports from anon,authenticated;
create policy "read own profile" on public.profiles for select to authenticated using ((select auth.uid())=user_id);
create policy "read own reports" on public.reports for select to authenticated using ((select auth.uid())=reporter_id);
comment on table public.pings is 'Private by default; no public publishing until identity, venue and authorization enforcement is implemented.';
